CREATE TABLE public.inbox_channel_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,channel text NOT NULL CHECK(channel IN('email','chat','linkedin')),account_id uuid NOT NULL,conversation_id uuid NOT NULL,event_key text NOT NULL,message_id uuid,inbound_id uuid,actor_id uuid,assigned_to uuid,previous_status text,status text,occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),occurrence_key text NOT NULL,envelope_id uuid NOT NULL,UNIQUE(workspace_id,event_key,occurrence_key));
GRANT SELECT(id,workspace_id,channel,account_id,conversation_id,event_key,message_id,inbound_id,actor_id,assigned_to,previous_status,status,occurred_at) ON public.inbox_channel_occurrences TO authenticated;
GRANT ALL ON public.inbox_channel_occurrences TO service_role;
ALTER TABLE public.inbox_channel_occurrences ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.inbox_channel_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,channel text NOT NULL,account_id uuid NOT NULL,conversation_id uuid NOT NULL,provider_id text NOT NULL,message_id uuid,provenance text NOT NULL CHECK(provenance IN('gmail_incremental','widget_session','unipile_signed','human_transition','confirmed_response')),envelope_hash text NOT NULL CHECK(envelope_hash ~ '^[a-f0-9]{64}$'),body_hash text,occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),actor_id uuid,UNIQUE(channel,account_id,provider_id));
GRANT ALL ON public.inbox_channel_evidence TO service_role;
ALTER TABLE public.inbox_channel_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inbox_channel_evidence FROM PUBLIC,anon,authenticated;
CREATE TABLE public.inbox_workflow_activations (workflow_id uuid PRIMARY KEY REFERENCES public.workflows(id) ON DELETE CASCADE,workspace_id uuid NOT NULL,workflow_version integer NOT NULL,activated_at timestamptz NOT NULL);
GRANT ALL ON public.inbox_workflow_activations TO service_role;
ALTER TABLE public.inbox_workflow_activations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inbox_workflow_activations FROM PUBLIC,anon,authenticated;
CREATE TABLE public.gmail_workflow_pending (account_id uuid NOT NULL REFERENCES public.email_accounts(id) ON DELETE CASCADE,provider_id text NOT NULL,workspace_id uuid NOT NULL,provenance text NOT NULL CHECK(provenance IN('incremental','history')),observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),done_at timestamptz,PRIMARY KEY(account_id,provider_id));
GRANT ALL ON public.gmail_workflow_pending TO service_role;
ALTER TABLE public.gmail_workflow_pending ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.gmail_workflow_pending FROM PUBLIC,anon,authenticated;
CREATE FUNCTION techerp_api.inbox_event_channel(p_key text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$ SELECT CASE WHEN p_key IN('shared.email.message_received','shared.email.conversation_created','shared.email.conversation_assigned','shared.email.first_response') THEN 'email' WHEN p_key IN('shared.chat.message_received','shared.chat.conversation_created','shared.chat.conversation_assigned','shared.chat.conversation_status_changed','shared.chat.first_response') THEN 'chat' WHEN p_key IN('shared.linkedin.message_received','shared.linkedin.conversation_created','shared.linkedin.conversation_status_changed','shared.linkedin.first_response') THEN 'linkedin' END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_event_channel(text) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION techerp_api.notification_business_category(p_key text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$ SELECT CASE WHEN p_key='shared.message.received' OR techerp_api.inbox_event_channel(p_key) IS NOT NULL THEN 'message' WHEN p_key IN('crm.deal.won','crm.deal.lost','crm.deal.stage_changed') THEN 'deal_stage' WHEN p_key IN('crm.proposal.accepted','contracts.signature.completed','projects.project.started','finance.invoice.received') THEN 'workflow' WHEN p_key IN('contracts.draft.accepted','people.approval.pending') THEN 'approval' WHEN p_key IN('ats.application.received','ats.interview.scheduled','ats.offer.accepted','people.employment.started') THEN 'hiring' WHEN p_key IN('contracts.contract.expiring','contracts.contract.renewal_due','projects.project.overdue','projects.task.overdue','projects.milestone.due','people.document.expiring','finance.payable.due','finance.receivable.due','finance.payable.overdue','finance.receivable.overdue') THEN 'task' END $$;
CREATE FUNCTION public.workflow_inbox_account_visible(p_workspace uuid,p_channel text,p_account uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$ DECLARE c jsonb:=public.work_access_context();k jsonb:=c->'keys';BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR c->>'workspace' IS DISTINCT FROM p_workspace::text OR c->>'actor' IS DISTINCT FROM auth.uid()::text OR NOT public.is_workspace_member(p_workspace,auth.uid()) OR NOT coalesce(k ?| ARRAY['system.workflows.view.own','system.workflows.view.team','system.workflows.view.workspace'],false) THEN RETURN false;END IF;
 IF p_channel='email' THEN RETURN coalesce(k ?| ARRAY['techsales.inbox.email.view.own','techsales.inbox.email.view.team','techsales.inbox.email.view.workspace'],false) AND EXISTS(SELECT 1 FROM public.email_accounts WHERE id=p_account AND workspace_id=p_workspace AND provider='gmail' AND status='connected');END IF;
 IF p_channel='chat' THEN RETURN p_account=p_workspace AND coalesce(k ?| ARRAY['techsales.inbox.chat.view.own','techsales.inbox.chat.view.team','techsales.inbox.chat.view.workspace'],false);END IF;
 IF p_channel='linkedin' THEN RETURN coalesce((k->>'techsales.inbox.linkedin.view.own')::boolean,false) AND EXISTS(SELECT 1 FROM public.unipile_accounts WHERE id=p_account AND workspace_id=p_workspace AND owner_id=auth.uid() AND status='connected');END IF;RETURN false;END $$;
REVOKE ALL ON FUNCTION public.workflow_inbox_account_visible(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.workflow_inbox_account_visible(uuid,text,uuid) TO authenticated,service_role,techerp_api_subject;
CREATE FUNCTION public.workflow_inbox_conversation_visible(p_workspace uuid,p_channel text,p_account uuid,p_conversation uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$ BEGIN
 IF NOT public.workflow_inbox_account_visible(p_workspace,p_channel,p_account) THEN RETURN false;END IF;
 IF p_channel='email' THEN RETURN EXISTS(SELECT 1 FROM public.email_threads WHERE id=p_conversation AND workspace_id=p_workspace AND account_id=p_account);END IF;
 IF p_channel='chat' THEN RETURN EXISTS(SELECT 1 FROM public.live_chat_sessions WHERE id=p_conversation AND workspace_id=p_workspace);END IF;
 IF p_channel='linkedin' THEN RETURN EXISTS(SELECT 1 FROM public.linkedin_conversations WHERE id=p_conversation AND workspace_id=p_workspace AND account_id=p_account);END IF;RETURN false;END $$;
REVOKE ALL ON FUNCTION public.workflow_inbox_conversation_visible(uuid,text,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.workflow_inbox_conversation_visible(uuid,text,uuid,uuid) TO authenticated,service_role,techerp_api_subject;
CREATE POLICY inbox_occurrence_read ON public.inbox_channel_occurrences FOR SELECT TO authenticated USING(public.workflow_inbox_conversation_visible(workspace_id,channel,account_id,conversation_id));
CREATE FUNCTION public.workflow_inbox_sources(p_workspace uuid,p_channel text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$ DECLARE sources jsonb;BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.work_access_context()->>'workspace' IS DISTINCT FROM p_workspace::text OR NOT public.is_workspace_member(p_workspace,auth.uid()) THEN RAISE EXCEPTION 'Workspace indisponível.' USING ERRCODE='42501';END IF;
 IF p_channel='email' THEN SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'label',a.email) ORDER BY a.email),'[]') INTO sources FROM (SELECT id,email FROM public.email_accounts WHERE workspace_id=p_workspace AND public.workflow_inbox_account_visible(p_workspace,'email',id) ORDER BY email LIMIT 100)a;
 ELSIF p_channel='linkedin' THEN SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'label','LinkedIn pessoal') ORDER BY a.id),'[]') INTO sources FROM (SELECT id FROM public.unipile_accounts WHERE workspace_id=p_workspace AND public.workflow_inbox_account_visible(p_workspace,'linkedin',id) ORDER BY id LIMIT 100)a;
 ELSIF p_channel='chat' THEN sources:=CASE WHEN public.workflow_inbox_account_visible(p_workspace,'chat',p_workspace) THEN jsonb_build_array(jsonb_build_object('id',p_workspace,'label','Chat do site deste workspace')) ELSE '[]'::jsonb END;
 ELSE RAISE EXCEPTION 'Canal inválido.' USING ERRCODE='22023';END IF;RETURN jsonb_build_object('workspace_id',p_workspace,'channel',p_channel,'sources',sources);END $$;
REVOKE ALL ON FUNCTION public.workflow_inbox_sources(uuid,text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.workflow_inbox_sources(uuid,text) TO authenticated;
CREATE FUNCTION techerp_api.inbox_account_current(p_workspace uuid,p_channel text,p_account uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE p_channel WHEN 'email' THEN EXISTS(SELECT 1 FROM public.email_accounts WHERE id=p_account AND workspace_id=p_workspace AND provider='gmail' AND status='connected') WHEN 'linkedin' THEN EXISTS(SELECT 1 FROM public.unipile_accounts a WHERE a.id=p_account AND a.workspace_id=p_workspace AND a.status='connected' AND public.is_workspace_member(p_workspace,a.owner_id)) WHEN 'chat' THEN p_account=p_workspace AND EXISTS(SELECT 1 FROM public.workspaces WHERE id=p_workspace) ELSE false END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_account_current(uuid,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION techerp_api.inbox_snapshot(p_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT jsonb_build_object('id',id,'workspace_id',workspace_id,'channel',channel,'account_id',account_id,'conversation_id',conversation_id,'event_key',event_key,'message_id',message_id,'inbound_id',inbound_id,'actor_id',actor_id,'assigned_to',assigned_to,'previous_status',previous_status,'status',status,'occurred_at',occurred_at) FROM public.inbox_channel_occurrences WHERE id=p_id $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_snapshot(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION techerp_api.inbox_subject_conversation(p_workspace uuid,p_user uuid,p_channel text,p_account uuid,p_conversation uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE allowed boolean;BEGIN
 IF p_user IS NULL OR NOT public.is_workspace_member(p_workspace,p_user) OR current_setting('app.api_subject',true)='on' THEN RETURN false;END IF;
 INSERT INTO techerp_api.subject_sessions(txid,user_id,workspace_id,api_key_id,prev_claims) VALUES(txid_current(),p_user,p_workspace,p_conversation,current_setting('request.jwt.claims',true));
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated','aud','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',p_user::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('app.api_subject','on',true);
 allowed:=public.workflow_inbox_conversation_visible(p_workspace,p_channel,p_account,p_conversation);PERFORM techerp_api.leave();RETURN coalesce(allowed,false);END $$;
ALTER FUNCTION techerp_api.inbox_subject_conversation(uuid,uuid,text,uuid,uuid) OWNER TO techerp_api_subject;
REVOKE ALL ON FUNCTION techerp_api.inbox_subject_conversation(uuid,uuid,text,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION techerp_api.inbox_subject_conversation(uuid,uuid,text,uuid,uuid) TO postgres;
CREATE FUNCTION techerp_api.inbox_subject_visible(p_workspace uuid,p_user uuid,p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE o record;BEGIN SELECT * INTO o FROM public.inbox_channel_occurrences WHERE id=p_id AND workspace_id=p_workspace;IF NOT FOUND THEN RETURN false;END IF;RETURN techerp_api.inbox_subject_conversation(p_workspace,p_user,o.channel,o.account_id,o.conversation_id);END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_subject_visible(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION techerp_api.inbox_subject_visible(uuid,uuid,uuid) TO postgres,techerp_api_subject;
